package vjezbe5;

import java.util.Scanner;

public class IspitivanjeStringova {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		Scanner u = new Scanner (System.in);
		System.out.println("Unesi tekst: ");
		String tekst1 = u.nextLine();
		System.out.println("Unesi drugi tekst= ");
		String tekst2 = u.nextLine();
		
		if(tekst1.equalsIgnoreCase(tekst2)) {
			System.out.println("Tekstovi su isti: ");
		}else {
			System.out.println("Tekstovi su razliciti: ");
		
		
		
		
		
		
		
	}

}
}